-- YG-1247 toplu düzeltme değişiklik kaydı; YG-1248 etki uzlaştırması olmadan kapanmaz.
CREATE TABLE toplu_duzeltme (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), veri_kumesi text NOT NULL, kapsam text NOT NULL, gerekce text NOT NULL, ornek_dogrulama text NOT NULL, yedek_ref uuid NOT NULL REFERENCES yedek_kaydi (kimlik), betik_surumu text NOT NULL, betik_ozeti text NOT NULL CHECK (betik_ozeti ~ '^[0-9a-f]{64}$'), beklenen_kayit integer NOT NULL CHECK (beklenen_kayit > 0), gerceklesen_kayit integer, sonuc_kontrolu text, fark_aciklamasi text, etki_uzlastirma jsonb, durum text NOT NULL DEFAULT 'Onayda' CHECK (durum IN ('Onayda', 'Onaylandı', 'Reddedildi', 'Uygulandı', 'Kapandı')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), uygulama_zamani timestamptz, kapanis_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON toplu_duzeltme TO yatonet_uygulama;
